  output              io_push_ready,
  input      [71:0]   io_push_payload,
  output              io_pop_valid,
  input               io_pop_ready,
  output     [71:0]   io_pop_payload,
  input               io_flush,
  output reg [6:0]    io_occupancy,
  output reg [6:0]    io_availability,
